/* Emergency Orbit Map Card v0.1.1-alpha */
const TAG='emergency-orbit-map-card';
const ML='5.24.0';
const MLJS=[`https://cdn.jsdelivr.net/npm/maplibre-gl@${ML}/dist/maplibre-gl.js`,`https://unpkg.com/maplibre-gl@${ML}/dist/maplibre-gl.js`];
const MLCSS=[`https://cdn.jsdelivr.net/npm/maplibre-gl@${ML}/dist/maplibre-gl.css`,`https://unpkg.com/maplibre-gl@${ML}/dist/maplibre-gl.css`];
const DEFAULTS={
  title:'Emergency Orbit',demo_mode:false,
  entities:{incidents:'sensor.abc_emergency_home_nearby_incidents',nearest:'sensor.abc_emergency_home_nearest_incident',inside_polygon:'binary_sensor.abc_emergency_home_inside_polygon'},
  region:{mode:'home',label:'Local emergency region',radius_km:40},
  map:{height:520,style_url:'https://tiles.openfreemap.org/styles/dark',terrain:true,terrain_url:'https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png',overview_pitch:50,incident_pitch:62,incident_zoom:14.2},
  camera:{orbit:true,orbit_duration:22000,auto_return:true,auto_return_delay:30000}
};
const LEVEL={none:{r:0,c:'#4f8cff',t:'INFORMATION'},minor:{r:1,c:'#4f8cff',t:'INFORMATION'},moderate:{r:2,c:'#f5ce35',t:'ADVICE'},severe:{r:3,c:'#ff812d',t:'WATCH AND ACT'},extreme:{r:4,c:'#ff414b',t:'EMERGENCY WARNING'}};
let loader;
const merge=(a,b)=>Object.fromEntries(Object.keys({...a,...b}).map(k=>[k,a[k]&&b?.[k]&&typeof a[k]==='object'&&typeof b[k]==='object'&&!Array.isArray(a[k])?merge(a[k],b[k]):b?.[k]??a[k]]));
const num=v=>Number.isFinite(+v)?+v:null;
const clean=v=>{const s=String(v??'').trim();return !s||['unknown','unavailable','none','null'].includes(s.toLowerCase())?'':s};
const level=v=>{const s=String(v??'none').toLowerCase().replace(/[^a-z]+/g,'_');if(['emergency_warning','emergency','extreme'].includes(s))return'extreme';if(['watch_and_act','watch','severe'].includes(s))return'severe';if(['advice','moderate'].includes(s))return'moderate';if(['information','info','minor'].includes(s))return'minor';return'none'};
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const icon=t=>{t=String(t).toLowerCase();if(t.includes('fire'))return'🔥';if(t.includes('flood'))return'≋';if(t.includes('storm')||t.includes('thunder'))return'ϟ';if(t.includes('wind')||t.includes('cyclone'))return'↯';if(t.includes('traffic')||t.includes('road')||t.includes('vehicle'))return'⚠';if(t.includes('rescue'))return'✚';return'!'};
function loadOne(url){return new Promise((ok,no)=>{const s=document.createElement('script');s.src=url;s.async=true;s.crossOrigin='anonymous';const timer=setTimeout(()=>{s.remove();no(Error(`Timed out loading ${url}`))},15000);s.onload=()=>{clearTimeout(timer);window.maplibregl?ok(window.maplibregl):(s.remove(),no(Error(`MapLibre loaded without window.maplibregl: ${url}`)))};s.onerror=()=>{clearTimeout(timer);s.remove();no(Error(`Failed to load ${url}`))};document.head.append(s)})}
function load(){if(window.maplibregl)return Promise.resolve(window.maplibregl);if(loader)return loader;loader=(async()=>{const errors=[];for(const url of MLJS){try{return await loadOne(url)}catch(e){errors.push(e.message)}}throw Error(`MapLibre failed to load. ${errors.join(' | ')}`)})();loader.catch(()=>{loader=null});return loader}
function dest([lon,lat],bearing,km){const R=6371,d=km/R,b=bearing*Math.PI/180,p=lat*Math.PI/180,l=lon*Math.PI/180,p2=Math.asin(Math.sin(p)*Math.cos(d)+Math.cos(p)*Math.sin(d)*Math.cos(b)),l2=l+Math.atan2(Math.sin(b)*Math.sin(d)*Math.cos(p),Math.cos(d)-Math.sin(p)*Math.sin(p2));return[((l2*180/Math.PI+540)%360)-180,p2*180/Math.PI]}
function region(cfg,hass){const home=[num(hass?.config?.longitude)??150.7,num(hass?.config?.latitude)??-34.05],r=cfg.region||{};if(r.mode==='custom')return{center:[num(r.longitude)??home[0],num(r.latitude)??home[1]],radius:num(r.radius_km)??40,label:r.label||'Custom region'};if(r.mode==='bounds'){const w=num(r.west),e=num(r.east),s=num(r.south),n=num(r.north);if([w,e,s,n].every(Number.isFinite))return{center:[(w+e)/2,(s+n)/2],bounds:[[w,s],[e,n]],label:r.label||'Defined region'}}return{center:home,radius:num(r.radius_km)??40,label:r.label||'Home region'}}
function point(attrs){const lat=num(attrs?.latitude??attrs?.lat),lon=num(attrs?.longitude??attrs?.lon??attrs?.lng);if(Number.isFinite(lat)&&Number.isFinite(lon))return[lon,lat];const c=attrs?.coordinates??attrs?.location;if(Array.isArray(c)&&c.length>1){const a=num(c[0]),b=num(c[1]);if(Number.isFinite(a)&&Number.isFinite(b))return Math.abs(a)<=90&&Math.abs(b)>90?[b,a]:[a,b]}return null}
class Card extends HTMLElement{
  static getStubConfig(){return{...DEFAULTS,demo_mode:true}}
  constructor(){super();this.attachShadow({mode:'open'});this.cfg=DEFAULTS;this.map=null;this.ready=false;this.prev=new Map();this.markers=new Map();this.inc=[];this.selected=null;this.token=0;this.timer=0;this.frame=0}
  setConfig(c){if(!c)throw Error('Configuration required');this.cfg=merge(DEFAULTS,c);this.render();if(this.isConnected)this.init()}
  set hass(h){this._hass=h;if(!this.shadowRoot.innerHTML)this.render();this.update()}
  connectedCallback(){this.init()}
  disconnectedCallback(){this.stop();this.map?.remove();this.map=null;this.ready=false}
  getCardSize(){return Math.ceil((num(this.cfg.map.height)??520)/50)}
  getGridOptions(){return{columns:12,rows:Math.ceil((num(this.cfg.map.height)??520)/56),min_columns:6,min_rows:4}}
  render(){const h=num(this.cfg.map.height)??520;this.shadowRoot.innerHTML=`${MLCSS.map(x=>`<link rel="stylesheet" href="${x}">`).join('')}<style>:host{display:block}ha-card{position:relative;overflow:hidden;background:#07101d;color:white;height:${h}px;border-radius:16px}.map{position:absolute;inset:0}.shade{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(2,6,14,.62),transparent 26%,transparent 68%,rgba(2,6,14,.84))}.head{position:absolute;top:14px;left:16px;right:16px;display:flex;justify-content:space-between;gap:12px;pointer-events:none}.title{font:700 16px system-ui}.region{font:600 11px system-ui;color:#b9c7db;text-transform:uppercase;letter-spacing:.12em}.panel{position:absolute;left:16px;right:16px;bottom:14px;padding:14px 16px;border:1px solid color-mix(in srgb,var(--sev) 70%,transparent);border-radius:14px;background:rgba(5,10,20,.88);backdrop-filter:blur(12px);display:grid;grid-template-columns:42px 1fr auto;gap:12px;align-items:center}.badge{width:42px;height:42px;border-radius:11px;display:grid;place-items:center;background:color-mix(in srgb,var(--sev) 18%,#07101d);color:var(--sev);font-size:23px}.sev{font:800 10px system-ui;color:var(--sev);letter-spacing:.11em}.type{font:800 13px system-ui}.headline{font:600 13px system-ui;margin-top:3px}.meta{font:500 11px system-ui;color:#aab7ca;margin-top:4px}.controls{display:flex;gap:6px}.controls button{border:1px solid rgba(255,255,255,.16);background:rgba(255,255,255,.08);color:white;border-radius:9px;padding:8px 10px;cursor:pointer}.clear{position:absolute;left:16px;bottom:16px;padding:10px 12px;border:1px solid rgba(255,255,255,.14);border-radius:12px;background:rgba(5,10,20,.74);font:600 12px system-ui;color:#c7d2e3}.marker{width:34px;height:34px;border:0;border-radius:50% 50% 50% 5px;transform:rotate(-45deg);background:var(--c);box-shadow:0 0 0 5px color-mix(in srgb,var(--c) 25%,transparent),0 8px 22px #0008;color:white;cursor:pointer}.marker span{display:block;transform:rotate(45deg);font-size:17px}.home{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:#07101d;border:2px solid #fff;color:#fff;font-size:17px;box-shadow:0 5px 18px #0009}.loading{position:absolute;inset:0;display:grid;place-items:center;padding:24px;text-align:center;font:600 13px system-ui;background:#07101d}@media(max-width:650px){.panel{grid-template-columns:36px 1fr}.badge{width:36px;height:36px}.controls{grid-column:1/-1;justify-content:flex-end}}</style><ha-card><div class="map"></div><div class="shade"></div><div class="head"><div><div class="title">${esc(this.cfg.title)}</div><div class="region"></div></div></div><div class="clear">No active emergency incidents</div><div class="panel" hidden><div class="badge"></div><div><div><span class="sev"></span> · <span class="type"></span></div><div class="headline"></div><div class="meta"></div></div><div class="controls"><button data-a="overview">Overview</button><button data-a="orbit">Orbit</button></div></div><div class="loading">Loading 3D emergency map…</div></ha-card>`;this.els={map:this.shadowRoot.querySelector('.map'),region:this.shadowRoot.querySelector('.region'),panel:this.shadowRoot.querySelector('.panel'),clear:this.shadowRoot.querySelector('.clear'),badge:this.shadowRoot.querySelector('.badge'),sev:this.shadowRoot.querySelector('.sev'),type:this.shadowRoot.querySelector('.type'),headline:this.shadowRoot.querySelector('.headline'),meta:this.shadowRoot.querySelector('.meta'),loading:this.shadowRoot.querySelector('.loading')};this.shadowRoot.querySelectorAll('button[data-a]').forEach(b=>b.onclick=()=>b.dataset.a==='overview'?this.overview(true):this.focus(this.inc.find(x=>x.id===this.selected)||this.inc[0],true))}
  async init(){if(this.map||!this.els)return;try{const ml=await load(),r=region(this.cfg,this._hass);this.ml=ml;this.els.region.textContent=r.label;this.map=new ml.Map({container:this.els.map,style:this.cfg.map.style_url,center:r.center,zoom:9,pitch:this.cfg.map.overview_pitch,bearing:-18,attributionControl:true});this.map.on('load',()=>{try{if(this.cfg.map.terrain){this.map.addSource('terrain',{type:'raster-dem',tiles:[this.cfg.map.terrain_url],tileSize:256,encoding:'terrarium'});this.map.setTerrain({source:'terrain',exaggeration:1.3})}}catch(e){console.warn(`[${TAG}] Terrain unavailable`,e)}this.ready=true;this.els.loading.hidden=true;this.home=new ml.Marker({element:Object.assign(document.createElement('div'),{className:'home',textContent:'⌂'})}).setLngLat([num(this._hass?.config?.longitude)??r.center[0],num(this._hass?.config?.latitude)??r.center[1]]).addTo(this.map);this.overview(false);this.update()});this.map.on('mousedown',()=>this.stop());this.map.on('error',e=>console.warn(`[${TAG}] Map error`,e?.error||e))}catch(e){console.error(`[${TAG}]`,e);this.els.loading.textContent=e.message}}
  collect(){if(this.cfg.demo_mode){const r=region(this.cfg,this._hass),types=[['Bushfire','severe'],['Flood','moderate'],['Storm Warning','extreme'],['Traffic Incident','minor']];return types.map((x,i)=>({id:'demo'+i,type:x[0],level:x[1],headline:`Demonstration ${x[0].toLowerCase()} incident`,point:dest(r.center,35+i*82,8+i*5),distance:8+i*5,direction:'near the selected region'}))}const e=this.cfg.entities,near=this._hass?.states?.[e.incidents],base=Array.isArray(near?.attributes?.incidents)?near.attributes.incidents:[],ids=Array.isArray(near?.attributes?.entity_ids)?near.attributes.entity_ids:[];return base.map((raw,i)=>{const slug=String(raw.id??'').toLowerCase().replace(/[^a-z0-9]+/g,'_'),id=ids.find(x=>slug&&String(x).endsWith(slug))??ids[i],geo=id?this._hass?.states?.[id]:null,a=geo?.attributes??{};const type=clean(a.event_type??raw.event_type??'Emergency incident');if(type.toLowerCase()==='other non-urgent alerts')return null;return{id:String(raw.id??id??i),type,level:level(a.alert_level??raw.alert_level),headline:clean(a.friendly_name??a.headline??raw.headline??'Incident details updating'),point:point(a)??point(raw),distance:num(geo?.state??raw.distance_km),direction:clean(a.direction??raw.direction),status:clean(a.status),updated:clean(a.updated)}}).filter(x=>x&&x.point).sort((a,b)=>LEVEL[b.level].r-LEVEL[a.level].r||(a.distance??9999)-(b.distance??9999))}
  update(){if(!this._hass&&!this.cfg.demo_mode)return;const list=this.collect(),old=this.prev;this.inc=list;this.prev=new Map(list.map(x=>[x.id,x.level]));if(this.ready)this.draw();const fresh=list.find(x=>!old.has(x.id)||LEVEL[x.level].r>LEVEL[old.get(x.id)||'none'].r);if(fresh&&this.ready)this.focus(fresh,true)}
  draw(){const active=new Set(this.inc.map(x=>x.id));for(const x of this.inc){let m=this.markers.get(x.id);if(!m){const el=document.createElement('button');el.className='marker';el.innerHTML=`<span>${icon(x.type)}</span>`;el.onclick=()=>this.focus(x,true);m={el,marker:new this.ml.Marker({element:el,anchor:'bottom'}).setLngLat(x.point).addTo(this.map)};this.markers.set(x.id,m)}m.marker.setLngLat(x.point);m.el.style.setProperty('--c',LEVEL[x.level].c)}for(const[id,m]of this.markers)if(!active.has(id)){m.marker.remove();this.markers.delete(id)}this.els.clear.hidden=!!this.inc.length;if(!this.inc.length)this.els.panel.hidden=true}
  focus(x,animate){if(!x||!this.ready)return;this.stop();this.selected=x.id;const s=LEVEL[x.level];this.els.panel.hidden=false;this.els.panel.style.setProperty('--sev',s.c);this.els.badge.textContent=icon(x.type);this.els.sev.textContent=s.t;this.els.type.textContent=x.type.toUpperCase();this.els.headline.textContent=x.headline;this.els.meta.textContent=[Number.isFinite(x.distance)?`${x.distance.toFixed(1)} km`:'',x.direction,x.status].filter(Boolean).join(' · ');this.map.flyTo({center:x.point,zoom:this.cfg.map.incident_zoom,pitch:this.cfg.map.incident_pitch,bearing:this.map.getBearing(),duration:animate?3400:0,essential:true});const t=++this.token;this.map.once('moveend',()=>{if(t!==this.token)return;this.cfg.camera.orbit?this.orbit(x,t):this.schedule(t)})}
  orbit(x,t){const start=performance.now(),d=Math.max(6000,num(this.cfg.camera.orbit_duration)??22000),b=this.map.getBearing();const step=n=>{if(t!==this.token)return;const p=Math.min(1,(n-start)/d),e=p<.5?2*p*p:1-((-2*p+2)**2)/2;this.map.jumpTo({center:x.point,bearing:b+360*e,pitch:this.cfg.map.incident_pitch});if(p<1)this.frame=requestAnimationFrame(step);else this.schedule(t)};this.frame=requestAnimationFrame(step)}
  schedule(t){if(!this.cfg.camera.auto_return)return;this.timer=setTimeout(()=>{if(t===this.token)this.overview(true)},num(this.cfg.camera.auto_return_delay)??30000)}
  overview(animate){if(!this.ready)return;this.stop();this.selected=null;this.els.panel.hidden=true;const r=region(this.cfg,this._hass);let bounds=r.bounds;if(!bounds){const sw=dest(r.center,225,r.radius),ne=dest(r.center,45,r.radius);bounds=[sw,ne]}this.map.fitBounds(bounds,{padding:60,duration:animate?1800:0,pitch:this.cfg.map.overview_pitch,bearing:-18,maxZoom:12,essential:true})}
  stop(){this.token++;cancelAnimationFrame(this.frame);clearTimeout(this.timer);this.frame=0;this.timer=0}
}
if(!customElements.get(TAG))customElements.define(TAG,Card);
window.customCards=window.customCards||[];if(!window.customCards.some(x=>x.type===TAG))window.customCards.push({type:TAG,name:'Emergency Orbit Map Card',description:'Live 3D emergency map with fly-in and orbit camera'});
console.info('%c EMERGENCY ORBIT MAP CARD %c v0.1.1-alpha ','color:white;background:#1976d2;padding:3px','color:#dbeafe;background:#0f172a;padding:3px');